import base64

def encode_cursor(item_id: str) -> str:
    return base64.b64encode(item_id.encode("utf-8")).decode("utf-8")

def decode_cursor(cursor_str: str) -> str:
    return base64.b64decode(cursor_str.encode("utf-8")).decode("utf-8")

