from typing import List, Optional
from models import Item, PageResult
from cursor import encode_cursor, decode_cursor

class Paginator:
    def __init__(self, dataset: List[Item]):
        self.dataset = dataset

    def query_page(self, limit: int, cursor: Optional[str] = None) -> PageResult:
        start_idx = 0
        if cursor:
            target_id = decode_cursor(cursor)
            for idx, item in enumerate(self.dataset):
                if item.id == target_id:
                    # Bug: uses start_idx = idx instead of idx + 1, including the cursor item again in the next page
                    start_idx = idx
                    break

        page_items = self.dataset[start_idx : start_idx + limit]
        next_cursor = None
        if start_idx + limit < len(self.dataset) and page_items:
            next_cursor = encode_cursor(page_items[-1].id)

        return PageResult(items=page_items, next_cursor=next_cursor)

